/* big_long: long run of every operation kind under random policy switches
 * Generated by gen/big_tests.py (19951 table operations). */
#include <stdio.h>
#include <string.h>
#include <stdint.h>
#include "myalloc.h"

#define NS 400
static unsigned char *P[NS];   /* live pointer per slot */
static unsigned char *Q[NS];   /* last pointer the slot gave up (stale) */
static size_t N[NS];           /* requested size per slot */
static unsigned SD[NS];        /* data pattern seed per slot */
static unsigned char ext_buf[256];

static inline unsigned char pat(unsigned seed, size_t i)
{
    return (unsigned char)(seed * 167u + i * 13u + (i >> 9));
}

static inline void fill_range(int s, size_t from, size_t to)
{
    for (size_t i = from; i < to; i++)
        P[s][i] = pat(SD[s], i);
}

static inline void verify(int s, const unsigned char *p, size_t len)
{
    for (size_t i = 0; i < len; i++)
        if (p[i] != pat(SD[s], i)) {
            printf("CORRUPT slot %d byte %zu\n", s, i);
            return;
        }
}

/* exp < 0: no check. exp 0: expect NULL. exp 1: expect non-NULL. */
static inline void M(int s, size_t n, unsigned seed, int exp)
{
    P[s] = my_malloc(n);
    N[s] = P[s] ? n : 0;
    SD[s] = seed;
    if (P[s])
        fill_range(s, 0, n);
    if (exp >= 0 && (P[s] != NULL) != exp)
        printf("MISMATCH malloc slot %d n %zu\n", s, n);
}

/* print 1: print outcome. Otherwise exp checks it (0 NULL, 1 ptr). */
static inline void C(int s, size_t a, size_t b, unsigned seed, int print, int exp)
{
    unsigned char *q = my_calloc(a, b);
    const char *what = "NULL";
    P[s] = q;
    N[s] = 0;
    SD[s] = seed;
    if (q) {
        size_t n = a * b;
        what = "zeroed";
        for (size_t i = 0; i < n; i++)
            if (q[i] != 0) {
                what = "NOT ZEROED";
                printf("CALLOC NOT ZEROED slot %d byte %zu\n", s, i);
                break;
            }
        N[s] = n;
        fill_range(s, 0, n);
    }
    if (print)
        printf("calloc slot %d: %s\n", s, what);
    else if (exp >= 0 && (q != NULL) != exp)
        printf("MISMATCH calloc slot %d\n", s);
}

/* Outcome codes: 0 NULL, 1 same pointer, 2 moved, 3 new (old was NULL). */
static const char *const RNAME[] = {"NULL", "same", "moved", "new"};

static inline void R(int s, size_t n, unsigned seed, int print, int exp)
{
    unsigned char *old = P[s];
    size_t on = N[s];
    int got;
    if (old)
        verify(s, old, on);
    else
        SD[s] = seed;
    unsigned char *q = my_realloc(old, n);
    if (!q) {
        got = 0;
        if (old && n == 0) {
            Q[s] = old;
            P[s] = NULL;
            N[s] = 0;
        }
    } else {
        got = q == old ? 1 : (old ? 2 : 3);
        size_t keep = on < n ? on : n;
        verify(s, q, keep);
        if (old && q != old)
            Q[s] = old;
        P[s] = q;
        N[s] = n;
        if (n > keep)
            fill_range(s, keep, n);
    }
    if (print)
        printf("realloc slot %d %zu: %s\n", s, n, RNAME[got]);
    else if (exp >= 0 && got != exp)
        printf("MISMATCH realloc slot %d n %zu got %s expected %s\n", s, n, RNAME[got], RNAME[exp]);
}

static inline void F(int s)
{
    if (P[s])
        verify(s, P[s], N[s]);
    my_free(P[s]);
    if (P[s])
        Q[s] = P[s];
    P[s] = NULL;
    N[s] = 0;
}

/* free / realloc through the slot's stale pointer (error cases only) */
static inline void FS(int s) { my_free(Q[s]); }
static inline void RS(int s, size_t n)
{
    if (my_realloc(Q[s], n) != NULL)
        printf("UNEXPECTED non-NULL from realloc of stale pointer\n");
}
/* pointer into the middle of a live block (invalid) */
static inline void FM(int s, size_t off) { my_free(P[s] + off); }
static inline void RM(int s, size_t off, size_t n)
{
    if (my_realloc(P[s] + off, n) != NULL)
        printf("UNEXPECTED non-NULL from realloc of interior pointer\n");
}
/* pointers outside the heap */
static inline void FX(void) { my_free(ext_buf + 32); }
static inline void FSTACK(void)
{
    unsigned char local[64];
    local[0] = 1;
    my_free(local + 32);
}
/* overwrite one guard byte (k in 0..7) of a live block */
static inline void G(int s, int k) { P[s][N[s] + (size_t)k] = 0x35; }

static inline void ISNULL(int s) { printf("slot %d: %s\n", s, P[s] ? "ptr" : "NULL"); }
static inline void BYTES(int s)
{
    printf("bytes slot %d: %02x %02x %02x\n", s, P[s][0], P[s][N[s] / 2], P[s][N[s] - 1]);
}
static inline void VERIFY_ALL(void)
{
    for (int s = 0; s < NS; s++)
        if (P[s])
            verify(s, P[s], N[s]);
}
static inline void D(void) { my_heap_dump(); }
static inline void L(void) { my_leak_report(); }
static inline void POL(int p) { my_set_policy(p); }
static inline void NOTE(const char *t) { printf("%s\n", t); }

