int main(void)
{
    for (size_t i = 0; i < sizeof OPS / sizeof OPS[0]; i++) {
        const struct op *o = &OPS[i];
        unsigned seed = (unsigned)i + 1;
        switch (o->k) {
        case 'm': M(o->s, o->a, seed, o->e); break;
        case 'c': C(o->s, o->a, o->b, seed, 0, o->e); break;
        case 'r': R(o->s, o->a, seed, 0, o->e); break;
        case 'f': F(o->s); break;
        case 'S': FS(o->s); break;
        case 'T': RS(o->s, o->a); break;
        case 'i': FM(o->s, o->a); break;
        case 'I': RM(o->s, o->a, o->b); break;
        case 'x': FX(); break;
        case 'g': G(o->s, (int)o->a); break;
        case 'p': POL((int)o->a); break;
        case 'd': D(); break;
        case 'v': VERIFY_ALL(); break;
        case 'l': L(); break;
        case 'n': my_free(NULL); break;
        }
    }
    return 0;
}
